sys_ws_operation.operation_script:
(function process(request, response) {
    if (!(gs.hasRole('x_espaco.leitura') || gs.hasRole('x_espaco.recepcionista') ||
          gs.hasRole('x_espaco.profissional') || gs.hasRole('x_espaco.gestor') || gs.hasRole('x_espaco.admin'))) {
        response.setStatus(403);
        return { error: { code: 403, message: 'Sem permissão para consultar este recurso.' } };
    }
    var page = parseInt(request.queryParams.page || '1', 10);
    var limit = Math.min(parseInt(request.queryParams.limit || '20', 10), 100);
    var search = request.queryParams.search || '';
    var offset = (page - 1) * limit;

    var gr = new GlideRecord('x_espaco_cliente');
    if (search) {
        gr.addQuery('nome', 'CONTAINS', search).addOrCondition('email', 'CONTAINS', search);
    }
    gr.orderBy('nome');
    gr.chooseWindow(offset, offset + limit);
    gr.query();

    var data = [];
    while (gr.next()) {
        data.push({
            sys_id: gr.getUniqueValue(),
            nome: gr.getValue('nome'),
            email: gr.getValue('email'),
            telefone: gr.getValue('telefone'),
            consentimento_lgpd: gr.getValue('consentimento_lgpd')
        });
    }

    var count = new GlideAggregate('x_espaco_cliente');
    if (search) {
        count.addQuery('nome', 'CONTAINS', search).addOrCondition('email', 'CONTAINS', search);
    }
    count.addAggregate('COUNT');
    count.query();
    var total = count.next() ? parseInt(count.getAggregate('COUNT'), 10) : 0;

    response.setStatus(200);
    return { data: data, meta: { page: page, limit: limit, total: total } };
})(request, response);
